import React from 'react';

import { RicosContext } from './../ricos-context/index.js';
import type { TocData } from './../ricos-schema/next-schema/index.js';
import type { TFunction } from './../ricos-types/index.js';

import type { TocHeading } from './heading-extraction.js';
import { getListTag, getMarker } from './markers.js';
import {
  alphabeticalIndexEntryListStyle,
  alphabeticalIndexNavListStyle,
  alphabeticalIndexSectionStyle,
  listDepthStyle,
  markerStyle,
  placeholderStyle,
  resolveViewStyles,
} from './resolve-styles.js';
import type { ResolvedViewStyles } from './resolve-styles.js';
import tocStyles from './toc-view-scss.js';
import { buildAlphabeticalGroups, buildTree } from './tree-builder.js';
import type { TreeItem } from './tree-builder.js';

type Props = {
  tocId?: string;
  data: TocData;
  headings: TocHeading[];
  mode: 'editor' | 'viewer';
  onNavigate?: (heading: TocHeading) => void;
  onSelect?: () => boolean;
};

export const getScrollBehavior = (): ScrollBehavior => {
  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') {
    return 'smooth';
  }

  return window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth';
};

const renderItems = ({
  items,
  data,
  depth,
  parentIndices,
  onNavigate,
  onSelect,
  getNextVisibleIndex,
  resolvedLinkStyle,
  resolvedListItemStyle,
}: {
  items: TreeItem[];
  data: TocData;
  depth: number;
  parentIndices: number[];
  onNavigate?: (heading: TocHeading) => void;
  onSelect?: () => boolean;
  getNextVisibleIndex: () => number;
  resolvedLinkStyle: React.CSSProperties;
  resolvedListItemStyle: React.CSSProperties;
}) => {
  const ListTag = getListTag(data.listStyle);

  return (
    <ListTag role="list" style={listDepthStyle(depth)}>
      {items.map((item, index) => {
        const indices = [...parentIndices, index + 1];
        const marker = getMarker({
          data,
          depth,
          indices,
          visibleIndex: getNextVisibleIndex(),
        });

        return (
          <li key={item.nodeId} style={resolvedListItemStyle}>
            <a
              href={`#${item.anchor}`}
              className={tocStyles.tocLink}
              onClick={event => {
                event.preventDefault();
                if (onSelect?.()) {
                  return;
                }
                onNavigate?.(item);
              }}
              style={{
                ...resolvedLinkStyle,
                marginLeft: 0,
              }}
            >
              {marker ? (
                <span aria-hidden="true" style={markerStyle}>
                  {marker}
                </span>
              ) : null}
              <span>{item.text}</span>
            </a>
            {data.indentation !== 'FLAT' && item.children.length > 0
              ? renderItems({
                  items: item.children,
                  data,
                  depth: depth + 1,
                  parentIndices: indices,
                  onNavigate,
                  onSelect,
                  getNextVisibleIndex,
                  resolvedLinkStyle,
                  resolvedListItemStyle,
                })
              : null}
          </li>
        );
      })}
    </ListTag>
  );
};

const renderAlphabeticalIndex = ({
  data,
  headings,
  tocId,
  onNavigate,
  onSelect,
  resolvedStyles,
  t,
}: Pick<Props, 'data' | 'headings' | 'tocId' | 'onNavigate' | 'onSelect'> & {
  resolvedStyles: ResolvedViewStyles;
  t: TFunction;
}) => {
  const groups = buildAlphabeticalGroups(headings);
  const tocAnchorPrefix = tocId || 'toc';
  const isCompact = data.listStyle === 'ALPHABETICAL_INDEX_COMPACT';

  return (
    <div>
      <ul role="list" style={alphabeticalIndexNavListStyle}>
        {groups.map(group => {
          const sectionAnchor = `${tocAnchorPrefix}-${group.letter.toLowerCase()}`;
          const firstHeading = group.items[0];

          if (!firstHeading) {
            return null;
          }

          return (
            <li key={group.letter}>
              <a
                href={isCompact ? `#${firstHeading.anchor}` : `#${sectionAnchor}`}
                aria-label={t('TocPlugin_AlphabeticalIndex_JumpTo', { letter: group.letter })}
                className={tocStyles.tocLink}
                onClick={event => {
                  event.preventDefault();
                  if (onSelect?.()) {
                    return;
                  }

                  if (isCompact) {
                    onNavigate?.(firstHeading);
                    return;
                  }

                  if (typeof document === 'undefined') {
                    return;
                  }
                  const target = document.getElementById(sectionAnchor);
                  target?.scrollIntoView?.({
                    behavior: getScrollBehavior(),
                    block: 'start',
                  });
                  target?.focus?.({ preventScroll: true });
                }}
                style={resolvedStyles.alphabeticalIndexGroupLinkStyle}
              >
                {group.letter}
              </a>
            </li>
          );
        })}
      </ul>

      {isCompact
        ? null
        : groups.map(group => {
            const sectionAnchor = `${tocAnchorPrefix}-${group.letter.toLowerCase()}`;

            return (
              <div key={group.letter} style={alphabeticalIndexSectionStyle}>
                <div
                  id={sectionAnchor}
                  tabIndex={-1}
                  role="heading"
                  aria-level={2}
                  style={resolvedStyles.alphabeticalIndexLetterStyle}
                >
                  {group.letter}
                </div>
                <div aria-hidden="true" style={resolvedStyles.alphabeticalIndexDividerStyle} />
                <ul role="list" style={alphabeticalIndexEntryListStyle}>
                  {group.items.map(item => (
                    <li key={item.nodeId} style={resolvedStyles.alphabeticalIndexEntryStyle}>
                      <a
                        href={`#${item.anchor}`}
                        className={tocStyles.tocLink}
                        onClick={event => {
                          event.preventDefault();
                          if (onSelect?.()) {
                            return;
                          }
                          onNavigate?.(item);
                        }}
                        style={resolvedStyles.alphabeticalIndexEntryLinkStyle}
                      >
                        {item.text}
                      </a>
                    </li>
                  ))}
                </ul>
              </div>
            );
          })}
    </div>
  );
};

export const TocView: React.FC<Props> = ({ data, headings, mode, onNavigate, onSelect, tocId }) => {
  const { t, theme } = React.useContext(RicosContext);
  const resolvedStyles = resolveViewStyles({ data, theme });

  if (headings.length === 0) {
    return mode === 'editor' ? (
      <div style={resolvedStyles.containerStyle}>
        <div style={placeholderStyle}>{t('TocPlugin_Placeholder')}</div>
      </div>
    ) : null;
  }

  const items =
    data.indentation !== 'FLAT'
      ? buildTree(headings)
      : headings.map(heading => ({
          ...heading,
          children: [],
        }));
  let visibleIndex = 0;
  const getNextVisibleIndex = () => {
    visibleIndex += 1;
    return visibleIndex;
  };

  return (
    <nav
      contentEditable={false}
      style={resolvedStyles.containerStyle}
      aria-label={t('TocPlugin_AriaLabel')}
    >
      {data.listStyle === 'ALPHABETICAL_INDEX' || data.listStyle === 'ALPHABETICAL_INDEX_COMPACT'
        ? renderAlphabeticalIndex({
            data,
            headings,
            tocId,
            onNavigate,
            onSelect,
            resolvedStyles,
            t,
          })
        : renderItems({
            items,
            data,
            depth: 0,
            parentIndices: [],
            onNavigate,
            onSelect,
            getNextVisibleIndex,
            resolvedLinkStyle: resolvedStyles.linkStyle,
            resolvedListItemStyle: resolvedStyles.listItemStyle,
          })}
    </nav>
  );
};
