import { definePmNodeConverter } from './../pm-converters/types.js';
import { removeNullValues } from './../pm-converters/utils.js';
import { generateId } from './../ricos-content/index.js';
import type { TocData } from './../ricos-schema/next-schema/index.js';
import { Node_Type } from './../ricos-schema/next-schema/index.js';

import { TOC_DEFAULTS } from './defaults.js';
import { TOC_TYPE } from './types.js';

export const tocConverter = definePmNodeConverter({
  toPm: {
    types: [Node_Type.TOC],
    convert: node => ({
      type: TOC_TYPE,
      attrs: {
        id: node.id ?? generateId(),
        ...TOC_DEFAULTS,
        ...removeNullValues(node.tocData ?? {}),
      },
    }),
  },
  fromPm: {
    types: [TOC_TYPE],
    convert: pmNode => {
      if (pmNode.type !== TOC_TYPE) {
        return undefined;
      }

      const { id, ...attrs } = pmNode.attrs || {};
      return {
        type: Node_Type.TOC,
        id: id ?? generateId(),
        nodes: [],
        tocData: {
          ...removeNullValues(attrs),
          indentation: attrs.indentation === 'NESTED' ? undefined : attrs.indentation,
          itemSpacing:
            attrs.itemSpacing === TOC_DEFAULTS.itemSpacing ? undefined : attrs.itemSpacing,
        } as unknown as TocData,
      };
    },
  },
});
