import { Delete } from '@wix/wix-ui-icons-common/lazy';
import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import type { IToolbarItem, ToolbarButton } from './../../ricos-types/index.js';
import type { ToolbarButtonAttributes, ToolbarButtonCommand } from './../../ricos-types/plugin-types.js';

import { PLUGIN_TOOLBAR_DELETE_BUTTON } from '../data-hooks.js';
import { getNodeInSelection } from '../resolvers/get-node-in-selection.js';
import { ToolbarButton as ToolbarButtonComponent } from '../toolbar-button/toolbar-button.js';
import { PLUGIN_TOOLBAR_BUTTON_ID } from './plugin-toolbar-buttons-ids.js';

export const createDeleteButton = ({
  attributes,
  command,
  tooltip,
}: {
  command?: ToolbarButtonCommand;
  attributes?: ToolbarButtonAttributes;
  tooltip?: string;
} = {}): ToolbarButton => {
  return {
    id: PLUGIN_TOOLBAR_BUTTON_ID.DELETE,
    type: 'toggle',
    icon: Delete,
    attributes: {
      selectedNode: getNodeInSelection,
      ...attributes,
    },
    dataHook: PLUGIN_TOOLBAR_DELETE_BUTTON,
    tooltip: tooltip ? tooltip : 'DeleteButton_Tooltip',
    renderer: toolbarItem => {
      return <DeleteButton toolbarItem={toolbarItem} />;
    },
    command:
      command ||
      (({ tiptapEditor, attributes }) => {
        tiptapEditor.chain().focus().deleteNode(attributes.selectedNode.attrs.id).run();
      }),
  };
};

const DeleteButton: React.FC<{
  toolbarItem: IToolbarItem;
  dataHook?: string;
}> = ({ toolbarItem, dataHook }) => {
  const { t } = useContext(RicosContext) || {};

  const onClick = toolbarItem.commands.click;

  return (
    <ToolbarButtonComponent
      prefix={Delete}
      onClick={() => (onClick ? onClick() : toolbarItem.commands.delete())}
      dataHook={dataHook}
      tooltip={t('DeleteButton_Tooltip')}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
