import { anyCssColorToHex } from './../ricos-styles/themeStrategy/theme-utils.js';
import { isThemeColorToken } from './/theme-color-token.js';
import { getHexColorFromAlpha } from './../wix-rich-content-common/index.js';

type ResolveColorToDisplayHexOptions = {
  preserveAlpha?: boolean;
};

// Strip alpha before conversion only for document color values; CSS strings
// like `rgba(...)` must be converted first to avoid slicing arbitrary text.
const stripAlphaSafely = (color: string): string =>
  color.startsWith('#') || isThemeColorToken(color)
    ? (getHexColorFromAlpha(color) ?? color)
    : color;

/**
 * Converts a document color value into a picker-safe hex string for previews and inputs.
 * Returns `undefined` when the color depends on missing CSS vars in the current container.
 */
export const resolveColorToDisplayHex = (
  color: string | undefined,
  containerElement?: HTMLElement | null,
  { preserveAlpha = false }: ResolveColorToDisplayHexOptions = {}
): string | undefined => {
  const normalizedColor = (preserveAlpha ? color : color && stripAlphaSafely(color))?.trim();
  if (!normalizedColor) {
    return undefined;
  }

  const finalize = (hex: string) =>
    (preserveAlpha ? hex : (getHexColorFromAlpha(hex) ?? hex)).toUpperCase();

  if (!containerElement) {
    return normalizedColor.startsWith('#') ? finalize(normalizedColor) : undefined;
  }

  try {
    return finalize(anyCssColorToHex(normalizedColor, containerElement));
  } catch {
    return normalizedColor.startsWith('#') ? finalize(normalizedColor) : undefined;
  }
};
