import { Box, FormField, Thumbnail, Tooltip } from '@wix/design-system';
import React, { useContext } from 'react';

import { ZIndexContext } from './../ricos-context/index.js';
import { usePanelContainerElement } from './../ui-components/index.js';

type TogglesWithLabelProps<T extends string> = {
  label: string;
  infoContent?: string;
  value: T;
  options: { label: string; value: T; icon: React.ReactNode; dataHook: string }[];
  onChange: (value: T) => void;
};

export const TogglesWithLabel = <T extends string>({
  label,
  infoContent,
  value,
  options,
  onChange,
}: TogglesWithLabelProps<T>) => {
  const containerEl = usePanelContainerElement();
  const zIndexService = useContext(ZIndexContext);
  const zIndex = zIndexService.getZIndex('DIALOG');

  return (
    <FormField
      label={label}
      labelPlacement="left"
      labelWidth="1fr"
      infoContent={infoContent}
      infoTooltipProps={{ appendTo: containerEl, zIndex }}
    >
      <Box direction="horizontal" gap={'SP1'} align="left">
        {options.map(option => (
          <Tooltip
            key={option.value}
            size="small"
            content={option.label}
            appendTo={containerEl}
            zIndex={zIndex}
          >
            <Thumbnail
              size="tiny"
              selected={value === option.value}
              onClick={() => onChange(option.value)}
              noPadding
              height={30}
              contentAlignment="center"
              textPosition="inside"
              image={
                <Box width={30} height={30} align="center" verticalAlign="middle">
                  {option.icon}
                </Box>
              }
              dataHook={option.dataHook}
            />
          </Tooltip>
        ))}
      </Box>
    </FormField>
  );
};
