import type { TocHeading } from './heading-extraction.js';

export type TreeItem = TocHeading & {
  children: TreeItem[];
};

export const buildTree = (headings: TocHeading[]): TreeItem[] => {
  const roots: TreeItem[] = [];
  const stack: TreeItem[] = [];

  headings.forEach(heading => {
    const item: TreeItem = {
      ...heading,
      children: [],
    };

    while (stack.length > 0 && stack[stack.length - 1]!.level >= heading.level) {
      stack.pop();
    }

    const parent = stack[stack.length - 1];

    if (parent) {
      parent.children.push(item);
    } else {
      roots.push(item);
    }

    stack.push(item);
  });

  return roots;
};

const alphabeticalIndexCollator: { compare: (a: string, b: string) => number } = (() => {
  try {
    return new Intl.Collator(undefined, { sensitivity: 'base', numeric: true });
  } catch {
    return { compare: (a, b) => a.localeCompare(b) };
  }
})();

const getAlphabeticalIndexLetter = (text: string) => {
  const firstCharacter = text.trim().charAt(0).toUpperCase();
  return /^[A-Z]$/.test(firstCharacter) ? firstCharacter : '#';
};

export const buildAlphabeticalGroups = (headings: TocHeading[]) => {
  const sortedHeadings = [...headings].sort((left, right) => {
    const textComparison = alphabeticalIndexCollator.compare(left.text, right.text);

    if (textComparison !== 0) {
      return textComparison;
    }

    return alphabeticalIndexCollator.compare(left.nodeId, right.nodeId);
  });

  return sortedHeadings.reduce<
    {
      letter: string;
      items: TocHeading[];
    }[]
  >((groups, heading) => {
    const letter = getAlphabeticalIndexLetter(heading.text);
    const existingGroup = groups[groups.length - 1];

    if (!existingGroup || existingGroup.letter !== letter) {
      groups.push({
        letter,
        items: [heading],
      });
      return groups;
    }

    existingGroup.items.push(heading);
    return groups;
  }, []);
};
