import type React from 'react';

import type { RicosContext } from './../ricos-context/index.js';
import type { TocData } from './../ricos-schema/next-schema/index.js';
import { resolveCssColor } from './../_shared/resolve-css-color.js';

const DEFAULT_FONT_SIZE = '1rem';
const DEFAULT_ITEM_SPACING = 12;

export const placeholderStyle: React.CSSProperties = {
  color: 'rgba(22, 45, 61, 0.64)',
  fontStyle: 'italic',
  lineHeight: 1.5,
};

export const listDepthStyle = (depth: number): React.CSSProperties => ({
  listStyle: 'none',
  margin: 0,
  padding: 0,
  paddingLeft: depth > 0 ? 20 : 0,
});

export const linkStyle: React.CSSProperties = {
  alignItems: 'baseline',
  cursor: 'pointer',
  display: 'inline-flex',
  gap: 8,
  lineHeight: 1.45,
};

export const markerStyle: React.CSSProperties = {
  display: 'inline-block',
  flexShrink: 0,
  fontVariantNumeric: 'tabular-nums',
  minWidth: 20,
};

export const alphabeticalIndexNavListStyle: React.CSSProperties = {
  display: 'flex',
  flexWrap: 'wrap',
  gap: '8px 16px',
  listStyle: 'none',
  marginBottom: 24,
  marginTop: 0,
  padding: 0,
};

export const alphabeticalIndexSectionStyle: React.CSSProperties = {
  marginTop: 24,
};

export const alphabeticalIndexEntryListStyle: React.CSSProperties = {
  listStyle: 'none',
  margin: 0,
  padding: 0,
};

const toCssLength = (value: string | number | undefined) => {
  if (value === undefined) {
    return undefined;
  }

  return typeof value === 'number' ? `${value}px` : value;
};

const toHalfCssLength = (value: string | number | undefined) => {
  if (value === undefined) {
    return undefined;
  }

  return typeof value === 'number' ? `${value / 2}px` : `calc(${value} / 2)`;
};

const addPxToCssLength = (value: string | number | undefined, addition: number) => {
  if (value === undefined) {
    return undefined;
  }

  return typeof value === 'number' ? `${value + addition}px` : `calc(${value} + ${addition}px)`;
};

export const resolveViewStyles = ({
  data,
  theme,
}: {
  data: TocData;
  theme: React.ContextType<typeof RicosContext>['theme'];
}) => {
  const themeStyles = theme.customStyles?.toc;
  const color = resolveCssColor(
    data.color ?? themeStyles?.color ?? theme.customStyles?.link?.color
  );
  const fontSize = toCssLength(data.fontSize ?? themeStyles?.fontSize ?? DEFAULT_FONT_SIZE);
  const itemSpacing = data.itemSpacing ?? themeStyles?.itemSpacing ?? DEFAULT_ITEM_SPACING;
  const titleColor = resolveCssColor(
    themeStyles?.titleColor ??
      theme.customStyles?.p?.color ??
      (theme.palette && typeof theme.palette === 'object' && 'textColor' in theme.palette
        ? theme.palette.textColor
        : undefined) ??
      '#162D3D'
  );
  const sectionBorderColor = resolveCssColor(themeStyles?.borderColor ?? 'rgba(22, 45, 61, 0.24)');

  return {
    containerStyle: {
      paddingBlock: '8px',
      paddingInline: '0px',
    } as React.CSSProperties,
    linkStyle: {
      ...linkStyle,
      fontSize,
      ...(color ? { color } : {}),
    } as React.CSSProperties,
    listItemStyle: {
      margin: `${toHalfCssLength(itemSpacing)} 0`,
    } as React.CSSProperties,
    alphabeticalIndexLetterStyle: {
      fontSize: '2rem',
      fontWeight: 600,
      lineHeight: 1.1,
      margin: 0,
      color: titleColor,
    } as React.CSSProperties,
    alphabeticalIndexGroupLinkStyle: {
      ...linkStyle,
      fontSize,
      fontWeight: 500,
      marginRight: 8,
      ...(color ? { color } : {}),
    } as React.CSSProperties,
    alphabeticalIndexEntryLinkStyle: {
      ...linkStyle,
      fontSize,
      fontWeight: 600,
      marginBottom: 4,
      ...(color ? { color } : {}),
    } as React.CSSProperties,
    alphabeticalIndexEntryStyle: {
      marginTop: addPxToCssLength(itemSpacing, 4),
    } as React.CSSProperties,
    alphabeticalIndexDividerStyle: {
      borderTop: `1px solid ${sectionBorderColor}`,
      margin: '12px 0 20px',
    } as React.CSSProperties,
  };
};

export type ResolvedViewStyles = ReturnType<typeof resolveViewStyles>;
