import { List } from '@wix/wix-ui-icons-common/lazy';

import type { TocData } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { AddButton } from './../ricos-types/index.js';
import { INSERT_PLUGIN_BUTTONS, TOOLBARS } from './../editor-common/index.js';

import { INSERT_TOC_BUTTON } from './data-hooks.js';
import { TOC_DEFAULTS } from './defaults.js';
import { TOC_TYPE } from './types.js';

export const getAddButtons = (): AddButton[] => {
  return [
    {
      id: TOC_TYPE,
      icon: List,
      label: INSERT_PLUGIN_BUTTONS.TOC,
      dataHook: INSERT_TOC_BUTTON,
      tooltip: 'TocPlugin_InsertButton_Tooltip',
      toolbars: [TOOLBARS.MOBILE, TOOLBARS.FOOTER, TOOLBARS.SIDE],
      command: ({ publicCommands }) => {
        publicCommands.insertBlockWithBlankLines(TOC_TYPE, TOC_DEFAULTS as TocData);
        return true;
      },
      menuConfig: {
        group: 'advanced',
        tags: 'Toc_plugin_search_tags',
      },
    },
  ];
};
