import { Node_Type } from './../ricos-schema/next-schema/index.js';

type TextExtractableNode = {
  type?: string;
  textData?: { text?: string };
  nodes?: TextExtractableNode[];
};

export const getTextFromNodes = (nodes: TextExtractableNode[] = []): string =>
  nodes
    .map(node => {
      if (node.type === Node_Type.TEXT && node.textData?.text) {
        return node.textData.text;
      }

      if (Array.isArray(node.nodes)) {
        return getTextFromNodes(node.nodes);
      }

      return '';
    })
    .join('');
