import type { DropdownLayoutValueOption } from '@wix/design-system';
import { Box, Button, Divider, Dropdown, IconButton, Text } from '@wix/design-system';
import { Add, Replace } from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useContext, useEffect, useState } from 'react';

import { RicosContext } from './../../../../../ricos-context/index.js';
import type { Gradient } from './../../../../../ricos-types/color-palette-types.js';

import { ColorStops } from './color-stops.js';
import { MAX_GRADIENT_STOPS } from './consts.js';
import { CustomGradients } from './custom-gradients.js';
import {
  areGradientsEqual,
  findLargestGapMidpoint,
  roundPosition,
} from './gradient-picker-utils.js';
import { GradientPreview } from './gradient-preview.js';
import { GradientStopEditor, type OpenGradientStopColorPicker } from './gradient-stop-editor.js';

type GradientPickerProps = {
  value: Gradient;
  onChange: (gradient: Gradient) => void;
  customGradients?: Gradient[];
  onGradientAdded?: (gradient: Gradient) => void;
  onGradientDeleted?: (gradient: Gradient) => void;
  onColorPickerOpen?: OpenGradientStopColorPicker;
};

type GradientCenter = { x: number; y: number };

const getGradientAngle = (gradient: Gradient): number | undefined =>
  gradient.type === 'LINEAR' ? (gradient.angle ?? 90) : undefined;

const getGradientCenter = (gradient: Gradient): GradientCenter | undefined =>
  gradient.type === 'RADIAL' ? { x: gradient.centerX ?? 50, y: gradient.centerY ?? 50 } : undefined;

export const getGradientValueForType = ({
  currentGradient,
  nextType,
  lastAngle,
  lastCenter,
}: {
  currentGradient: Gradient;
  nextType: 'LINEAR' | 'RADIAL';
  lastAngle?: number;
  lastCenter?: GradientCenter;
}): Gradient =>
  nextType === 'LINEAR'
    ? {
        type: 'LINEAR',
        stops: currentGradient.stops,
        angle: lastAngle ?? 90,
      }
    : {
        type: 'RADIAL',
        stops: currentGradient.stops,
        centerX: lastCenter?.x ?? 50,
        centerY: lastCenter?.y ?? 50,
      };

export const GradientPicker: FC<GradientPickerProps> = ({
  value,
  onChange,
  customGradients = [],
  onGradientAdded,
  onGradientDeleted,
  onColorPickerOpen,
}) => {
  const { t } = useContext(RicosContext);
  const [containerElement, setContainerElement] = useState<HTMLDivElement | null>(null);
  const [lastAngle, setLastAngle] = useState<number | undefined>(() => getGradientAngle(value));
  const [lastCenter, setLastCenter] = useState<GradientCenter | undefined>(() =>
    getGradientCenter(value)
  );

  useEffect(() => {
    if (value.type === 'LINEAR') {
      setLastAngle(getGradientAngle(value));
    } else {
      setLastCenter(getGradientCenter(value));
    }
  }, [value]);

  const handlePreviewChange = (newValue: Gradient) => {
    onChange(newValue);

    if (newValue.type === 'LINEAR') {
      setLastAngle(newValue.angle);
    } else {
      setLastCenter({ x: newValue.centerX ?? 50, y: newValue.centerY ?? 50 });
    }
  };

  const handleTypeChange = (option: DropdownLayoutValueOption) => {
    if (option.id === value.type) {
      return;
    }

    onChange(
      getGradientValueForType({
        currentGradient: value,
        nextType: option.id as 'LINEAR' | 'RADIAL',
        lastAngle,
        lastCenter,
      })
    );
  };

  const handleAddGradient = () => {
    if (onGradientAdded) {
      const gradientExists = customGradients.some(gradient => areGradientsEqual(gradient, value));

      if (!gradientExists) {
        onGradientAdded(value);
      }
    }
  };

  const hasCustomGradients = customGradients.length > 0;
  const canAddStop = (value.stops?.length ?? 0) < MAX_GRADIENT_STOPS;

  return (
    <Box direction="vertical" width="100%" ref={setContainerElement}>
      <GradientPreview value={value} onChange={handlePreviewChange} />
      <Box direction="vertical" gap="SP3" padding="SP3">
        <Box align="space-between">
          <Box width="50%">
            <Dropdown
              ariaLabel={t('GradientPicker_Type_Label')}
              size="small"
              selectedId={value.type}
              options={[
                {
                  id: 'LINEAR',
                  value: t('GradientPicker_Type_Linear'),
                },
                {
                  id: 'RADIAL',
                  value: t('GradientPicker_Type_Radial'),
                },
              ]}
              onSelect={handleTypeChange}
              popoverProps={{ placement: 'bottom-start' }}
            />
          </Box>

          <IconButton
            ariaLabel={t('GradientPicker_Flip_Tooltip')}
            priority="secondary"
            size="small"
            onClick={() => {
              onChange({
                ...value,
                stops: value.stops
                  ?.slice()
                  .reverse()
                  .map(stop => ({
                    ...stop,
                    position: roundPosition(1 - (stop.position ?? 0)),
                  })),
              });
            }}
          >
            <Replace />
          </IconButton>
        </Box>

        <ColorStops
          value={value}
          onChange={onChange}
          onStopClick={index => {
            const stop = value.stops?.[index];
            if (stop) {
              onColorPickerOpen?.({
                originalIndex: index,
                stop,
                referenceElement: containerElement,
              });
            }
          }}
          canAddStop={canAddStop}
        />

        <Box align="space-between" verticalAlign="middle">
          <Text size="small" weight="bold">
            {t('GradientPicker_ColorStops_Title')}
          </Text>

          <IconButton
            ariaLabel={t('GradientPicker_AddStop_Tooltip')}
            priority="secondary"
            size="small"
            disabled={!canAddStop}
            onClick={() => {
              if (!canAddStop) {
                return;
              }
              const stops = value.stops ?? [];
              const newPosition = findLargestGapMidpoint(stops);
              const sorted = [...stops].sort((a, b) => (a.position ?? 0) - (b.position ?? 0));
              const after = sorted.find(s => (s.position ?? 0) >= newPosition);
              const newColor = after?.color ?? sorted[sorted.length - 1]?.color;
              onChange({
                ...value,
                stops: [...stops, { color: newColor, position: newPosition }],
              });
            }}
          >
            <Add />
          </IconButton>
        </Box>

        <Box direction="vertical" gap="SP3">
          {value.stops
            ?.map((stop, index) => ({ ...stop, originalIndex: index }))
            .sort((a, b) => (a.position ?? 0) - (b.position ?? 0))
            .map(stop => (
              <GradientStopEditor
                key={stop.originalIndex}
                value={value}
                stop={stop}
                onChange={onChange}
                originalIndex={stop.originalIndex}
                onColorPickerOpen={onColorPickerOpen}
              />
            ))}
        </Box>

        {onGradientAdded && (
          <Button size="small" fullWidth priority="secondary" onClick={handleAddGradient}>
            {t('GradientPicker_SaveGradient_Button')}
          </Button>
        )}
      </Box>

      {hasCustomGradients && (
        <>
          <Divider />

          <Box direction="vertical" padding="SP3" gap="SP3">
            <Text size="small" weight="bold">
              {t('GradientPicker_SavedGradients_Title')}
            </Text>
            <CustomGradients
              gradients={customGradients}
              selectedGradient={value}
              onGradientSelected={onChange}
              onGradientDeleted={onGradientDeleted}
            />
          </Box>
        </>
      )}
    </Box>
  );
};
